import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`painting-estimate`,heroTitle:`Generate painting estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded scope, sizes materials and labor, and drafts a detailed painting estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your project scope`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded a painting scope, walkthrough notes, or project photos. Build a complete painting estimate. (1) Extract the rooms, surfaces, prep work, coatings, quantities, access constraints, and exclusions from the uploaded files. (2) Estimate materials, labor hours, equipment, and specialty prep requirements. (3) Build pricing options with assumptions, add-ons, and margin. (4) Highlight any field-verification items or customer decisions that affect the estimate. (5) Deliver a detailed painting estimate with line-item pricing, scope summary, and next steps that is ready for the customer.`,heroOverlaySteps:[`Extracting rooms, surfaces, prep work, and coatings from your files`,`Sizing materials, labor, equipment, and specialty prep requirements`,`Building pricing options with assumptions, add-ons, and margin`,`Customer-ready painting estimate with scope summary, ready to send`],generatingSteps:[`Reading the uploaded scope notes, walkthrough details, and project photos`,`Designing an agent to organize material, labor, and prep requirements`,`Configuring estimate logic for assumptions, add-ons, and approvals`,`Preparing a detailed painting estimate with line items and next steps`],featureSectionTitle:`From walkthrough notes to approved estimate`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built around scope and prep work`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, walkthrough notes, and internal planning workflows stay connected so quoting and revisions move faster.`,`Surface counts. Prep assumptions. Materials. Labor. Computer gives your team a painting estimate draft that is ready for customer review.`],capabilitySectionTitle:`Your estimator, on autopilot`,capabilitySectionSubtitle:`Upload the scope, get back a painting estimate built around the real job.`,capabilityCards:[{title:`Scope Extraction`,description:`Computer can extract rooms, surfaces, prep requirements, coatings, and exclusions from walkthrough notes, project docs, and photos.`},{title:`Material & Labor Planning`,description:`Computer can size paint, prep materials, labor hours, and equipment needs so the estimate reflects the actual scope of work.`},{title:`Pricing Options`,description:`Computer can turn the scope into clear pricing with assumptions, add-ons, and room for optional upgrades or alternative finishes.`},{title:`Connect Your Tools`,description:`Computer can keep estimate drafts organized across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred prep assumptions, markup rules, and estimate structure across sessions so every quote stays consistent.`},{title:`Revision Support`,description:`Computer can update the estimate when the customer changes colors, finish level, or scope so the next draft is faster to produce.`}]});export{t as default};
